FUNCTION @@proc@@ (p_base IN NUMBER) RETURN NUMBER IS
    l_a NUMBER;
    l_b NUMBER;
    l_c NUMBER;
BEGIN
    l_a := p_base * @@num@@; -- @expect
    l_b := l_a + @@num@@; -- @expect
    l_c := l_b / @@num@@; -- @expect
    RETURN l_c;
END @@proc@@;

FUNCTION @@proc@@ (p_status IN VARCHAR2, p_type IN VARCHAR2, p_kind IN VARCHAR2) RETURN NUMBER IS
BEGIN
    IF p_status = '@@str@@' THEN -- @expect
        RETURN 1;
    ELSIF p_type = '@@str@@' THEN -- @expect
        RETURN 2;
    ELSIF p_kind = '@@str@@' THEN -- @expect
        RETURN 3;
    END IF;
    RETURN 0;
END @@proc@@;

PROCEDURE @@proc@@ (p_qty IN NUMBER, p_msg OUT VARCHAR2) IS
    l_fee NUMBER;
BEGIN
    IF p_qty > @@num@@ THEN -- @expect
        l_fee := p_qty - @@num@@; -- @expect
        p_msg := '@@str@@'; -- @expect
    ELSIF p_qty > 0 THEN
        l_fee := p_qty * @@num@@; -- @expect
        p_msg := '@@str@@' || TO_CHAR(l_fee); -- @expect
    ELSE
        l_fee := 0;
        DBMS_OUTPUT.PUT_LINE('@@str@@'); -- @expect
    END IF;
    @@proc2@@(l_fee);
END @@proc@@;

FUNCTION @@proc@@ (p_vals IN SYS.ODCINUMBERLIST) RETURN NUMBER IS
    l_sum  NUMBER := 0;
    l_rest NUMBER;
BEGIN
    FOR i IN 1 .. p_vals.COUNT LOOP
        l_sum := l_sum + p_vals(i) * @@num@@; -- @expect
        IF l_sum > @@num@@ THEN -- @expect
            EXIT;
        END IF;
    END LOOP;
    l_rest := MOD(l_sum, @@num@@); -- @expect
    RETURN l_rest;
END @@proc@@;

FUNCTION @@proc@@ (p_r IN NUMBER) RETURN NUMBER IS
    l_area NUMBER;
    l_circ NUMBER;
BEGIN
    l_area := @@num@@.25 * p_r * p_r; -- @expect
    l_circ := 2 * @@num@@.25 * p_r; -- @expect
    IF l_area > @@num@@.25 THEN -- @expect
        RETURN l_area;
    END IF;
    RETURN l_circ;
END @@proc@@;

