PROCEDURE @@proc@@ (p_qty IN NUMBER, p_msg OUT VARCHAR2) IS
    l_fee NUMBER;
BEGIN
    l_fee := p_qty * @@num@@;
    l_fee := l_fee + @@num2@@;
    IF l_fee > @@num@@ THEN
        p_msg := '@@str@@';
    ELSIF l_fee < @@num2@@ THEN
        p_msg := 'ok';
    ELSE
        p_msg := '@@str@@';
    END IF;
END @@proc@@;

PROCEDURE @@proc@@ (p_qty IN NUMBER, p_msg OUT VARCHAR2) IS
    c_rate CONSTANT NUMBER := @@num@@;
    c_tag  CONSTANT VARCHAR2(30) := '@@str@@';
    l_fee  NUMBER;
BEGIN
    l_fee := p_qty * c_rate;
    IF l_fee > c_rate THEN
        p_msg := c_tag;
    ELSIF l_fee < c_rate THEN
        p_msg := c_tag || ':low';
    ELSE
        p_msg := c_tag || ':even';
    END IF;
END @@proc@@;

FUNCTION @@proc@@ (p_first IN VARCHAR2, p_mid IN VARCHAR2, p_last IN VARCHAR2) RETURN VARCHAR2 IS
    l_name VARCHAR2(200);
BEGIN
    l_name := p_first;
    IF p_mid IS NOT NULL THEN
        l_name := l_name || ' ' || p_mid;
    END IF;
    l_name := l_name || ' ' || p_last;
    l_name := l_name || ' ' || TO_CHAR(SYSDATE, 'YYYY');
    RETURN l_name;
END @@proc@@;

PROCEDURE @@proc@@ (p_mode IN VARCHAR2, p_a OUT VARCHAR2, p_b OUT VARCHAR2, p_c OUT VARCHAR2) IS
BEGIN
    p_a := '';
    p_b := '';
    p_c := '';
    IF p_mode = '@@str@@' THEN
        p_a := UPPER(p_mode);
        p_b := LOWER(p_mode);
    END IF;
END @@proc@@;

FUNCTION @@proc@@ (p_n IN NUMBER) RETURN NUMBER IS
    l_acc NUMBER;
    l_cnt NUMBER;
BEGIN
    l_acc := 1;
    l_cnt := 0;
    IF p_n = 0 THEN
        RETURN 1;
    END IF;
    WHILE l_cnt < p_n LOOP
        l_acc := l_acc * 1 + l_cnt;
        l_cnt := l_cnt + 1;
    END LOOP;
    IF l_acc < 0 THEN
        RETURN 0;
    END IF;
    IF l_acc > 1 THEN
        RETURN l_acc - 1;
    END IF;
    RETURN 1;
END @@proc@@;
